<?php require __DIR__.'/config.php';
function field(string $key): void {
 global $fields; [$label,$type,$required]=$fields[$key];
 echo '<div class="field '.($type==='textarea'?'wide':'').'"><label for="'.e($key).'">'.e($label).($required?' *':'').'</label>';
 $attrs=' id="'.e($key).'" name="'.e($key).'" aria-describedby="error-'.e($key).'" '.($required?'required':'');
 if($type==='textarea') echo '<textarea'.$attrs.' rows="3" maxlength="20000"></textarea>';
 elseif($type==='select') echo '<select'.$attrs.'><option value="">Pilih '.e(strtolower($label)).'</option></select>';
 else echo '<input'.$attrs.' type="'.e($type).'" '.($type==='number'?'min="0" max="'.($key==='loss'?'1000000000000000':'10000000').'" step="1" value="0"':'maxlength="300"').'>';
 echo '<small class="error" id="error-'.e($key).'"></small></div>';
}
?>
